function SAEO_Dongle(){const a=0,b=1,c=3,d=4,e=5,f=9,g=200*SAEC_Events_CYCLE_UNIT;var h=0,i=0;this.cia_read=function(a,b,d){switch(SAEV_config.dongle){case c:{1==a&&0==b&&(0==h||SAEV_Events_currcycle>i+g?(d&=-17,h=0):d|=16);break}}return d},this.cia_write=function(d,e,f){switch(SAEV_config.dongle){case a:return;case b:{0==d&&0==e&&128&f&&(h^=1);break}case c:{1!=d||0!=e||128&f||(h=1,i=SAEV_Events_currcycle);break}}},this.joytest=function(){},this.joydat=function(c,d){switch(SAEV_config.dongle){case a:break;case b:{1==c&&0!=h&&(d+=256);break}case 2:{1==c&&(d&=-772,d|=257);break}case 8:{0==c&&(d&=-772,d|=257);break}case 6:{1==c&&(d&=-772,d|=769);break}case 7:{0==c&&(d&=-4,d|=0==h?1:2),h^=1;break}}return d},this.potgo=function(){switch(SAEV_config.dongle){case a:return;case d:case f:case e:h=(8*Math.random()>>>0)-3}},this.potgor=function(a){switch(SAEV_config.dongle){case f:a|=16384}return a},this.analogjoy=function(b,c){var g=-1;switch(SAEV_config.dongle){case a:return-1;case d:1==b&&0==c&&(g=73);break;case f:1==b&&(0==c&&(g=21),1==c&&(g=10));break;case e:1==b&&(1==c&&(g=80),0==c&&(g=43))}return 0<=g&&(g+=h,0>g&&(g=0)),g},this.reset=function(){h=0,i=0}}